def find_value_column(df, cal_info):
    expected = cal_info['calibration_data'].get('value_column_name', 'power_reading')
    expected_clean = str(expected).strip()
    cols = df.columns.tolist()
    for c in cols:
        if c.strip().lower() == expected_clean.lower():
            return c
    for c in cols:
        base = re.sub(r'_\d+$', '', c).strip().lower()
        if base == expected_clean.lower():
            return c
    common = ['power_reading', 'value', 'reading', 'power_out', 'output', 'generation', 'yield', 'kw_output', 'solar_yield', 'energy_wh', 'kw_reading', 'mwh_yield', 'energy_out', 'power_kw', 'yield_wh', 'kw_val', 'meter_value', 'sensor_out']
    for c in cols:
        cl = c.lower()
        for com in common:
            if com in cl:
                return c
    return cols[-1] if cols else None
