        try:
            start_str = f"2024 {w['month']} {w['day']} {w['start_time']}"
            end_str = f"2024 {w['month']} {w['day']} {w['end_time']}"
            fmt = "%Y %B %d %H:%M"
            try:
                w_start = tz.localize(datetime.strptime(start_str, fmt))
                w_end = tz.localize(datetime.strptime(end_str, fmt))
            except Exception:
                start_str = f"2024 {w['month'][:3]} {w['day']} {w['start_time']}"
                end_str = f"2024 {w['month'][:3]} {w['day']} {w['end_time']}"
                fmt = "%Y %b %d %H:%M"
                w_start = tz.localize(datetime.strptime(start_str, fmt))
                w_end = tz.localize(datetime.strptime(end_str, fmt))
        except Exception:
            continue
        if ts_local >= w_start and ts_local < w_end:
            return True
    return False
