def build_spike_intervals(df, tz):
    intervals = []
    if 'inverter_temperature_C' not in df.columns:
        return intervals
    try:
        df_ts = df.copy()
        df_ts['ts'] = pd.to_datetime(df_ts['timestamp'], errors='coerce')
        if df_ts['ts'].dt.tz is None:
            try:
                df_ts['ts'] = df_ts['ts'].dt.tz_localize(tz, ambiguous='infer', nonexistent='shift_forward')
            except Exception:
                df_ts['ts'] = df_ts['ts'].dt.tz_localize('UTC')
        df_ts['ts_utc'] = df_ts['ts'].dt.tz_convert('UTC')
        spikes = df_ts[df_ts['inverter_temperature_C'].astype(float) > 85.0]
        for _, row in spikes.iterrows():
            st = row['ts_utc']
            if pd.isna(st): continue
            start = st.to_pydatetime() if hasattr(st, 'to_pydatetime') else st
            end = start + timedelta(minutes=45)
            intervals.append((start, end))
    except Exception:
        pass
    return intervals

def in_spike(ts_utc, intervals):
    for s, e in intervals:
        if ts_utc >= s and ts_utc < e:
            return True
    return False
